{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "“普通”とか“あたりまえ”ってなんだろう",
        "今 手にある物差しでは",
        "全然上手く測れなくって",
        "吐いては また吸い込んだ不安に",
        "僕は為すがまま立ち尽くして"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "不器用で 空回って",
        "傷つくことから逃げている",
        "現実とノートで行ったり来たり 慰めて",
        "あぁ",
        "なんて生きづらい世界なんだろう",
        "だけど だけど"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "ぜんぶ ぜんぶ 僕だから",
        "うじうじ しくしく 僕だから",
        "ぜんぶ ぜんぶ 抱きしめて",
        "少し眠ろう",
        "痛いの痛いの飛んでゆけ",
        "悲しみにすべてを奪われないように",
        "僕は 僕の味方でいようよ",
        "まだまだ長い道の途中",
        "ちょっとくらい休憩したって",
        "誰にも叱られはしないから"
      ]
    }
  ],
  "section": "V2",
  "phrases": [
    {
      "id": "V2-01",
      "ja": "不器用で 空回って",
      "budget": {
        "min": 10,
        "max": 10
      },
      "pattern": [
        5,
        5
      ]
    },
    {
      "id": "V2-02",
      "ja": "傷つくことから逃げている",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": [
        8,
        4
      ]
    },
    {
      "id": "V2-03",
      "ja": "現実とノートで行ったり来たり 慰めて",
      "budget": {
        "min": 18,
        "max": 18
      },
      "pattern": [
        4,
        3,
        3,
        3,
        5
      ]
    },
    {
      "id": "V2-05",
      "ja": "なんて生きづらい世界なんだろう",
      "budget": {
        "min": 11,
        "max": 11
      },
      "pattern": [
        6,
        5
      ]
    },
    {
      "id": "V2-06",
      "ja": "だけど だけど",
      "budget": {
        "min": 6,
        "max": 6
      },
      "pattern": [
        3,
        3
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "笨拙地 兜着圈"
        },
        {
          "id": "V2-02",
          "zh": "总从伤痛面前 转身逃开"
        },
        {
          "id": "V2-03",
          "zh": "现实 笔记 来来回回 找安慰"
        },
        {
          "id": "V2-05",
          "zh": "这世界 怎么这样难活"
        },
        {
          "id": "V2-06",
          "zh": "可是啊 可是啊"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "笨拙地 徒劳空转"
        },
        {
          "id": "V2-02",
          "zh": "逃避着那些伤害"
        },
        {
          "id": "V2-03",
          "zh": "现实与笔记本间来回 寻求安慰"
        },
        {
          "id": "V2-05",
          "zh": "多么难以生存的世界啊"
        },
        {
          "id": "V2-06",
          "zh": "但是 但是"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "笨拙的双手 原地空转圈"
        },
        {
          "id": "V2-02",
          "zh": "知道会疼就绕开走 躲进纸页"
        },
        {
          "id": "V2-03",
          "zh": "台灯底下 纸页间 来回跑 写一行 就当被安慰"
        },
        {
          "id": "V2-05",
          "zh": "这世界太难熬 人活得发慌"
        },
        {
          "id": "V2-06",
          "zh": "可是我 还是想"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "太笨拙了我 总是空转"
        },
        {
          "id": "V2-02",
          "zh": "我一直在逃避着 所有的伤痛"
        },
        {
          "id": "V2-03",
          "zh": "现实和笔记本之间 来回地往返着 来安慰我"
        },
        {
          "id": "V2-05",
          "zh": "多么难活下去的这个世界"
        },
        {
          "id": "V2-06",
          "zh": "可是啊 可是啊"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "太笨拙的我 空转个不停"
        },
        {
          "id": "V2-02",
          "zh": "我总是在害怕受伤 转身逃亡"
        },
        {
          "id": "V2-03",
          "zh": "现实冷硬 纸页暖 来回跑 哄哄我 在字里安眠"
        },
        {
          "id": "V2-05",
          "zh": "这世界真难活 真难喘口气"
        },
        {
          "id": "V2-06",
          "zh": "可是啊 可是啊"
        }
      ]
    }
  ]
}

